#include "CescSensorClient.h"
#include "CescSession.h"
CescSensorClient::CescSensorClient(CescSession*s,QObject*p):QObject(p),m_session(s){connect(s->transactions(),&CescTransactionManager::completed,this,[this](quint16,quint8 svc,quint8 cmd,Cesc::Status st,const QByteArray&b){if(svc!=2)return;if(st!=Cesc::Status::Ok){emit commandFailed(tr("Sensor command failed: %1").arg(quint16(st)));return;}qsizetype p=0;if(cmd==0){quint8 count,id,type,caps;QStringList names;if(!Cesc::readU8(b,p,count))return;for(int i=0;i<count;++i){QString name;if(!Cesc::readU8(b,p,id)||!Cesc::readU8(b,p,type)||!Cesc::readU8(b,p,caps)||!Cesc::readString(b,p,name))return;names<<name;}emit sensorsEnumerated(names);}else if(cmd==1){Sample x;quint8 reserved,calibrated;if(!Cesc::readU8(b,p,x.sensorId)||!Cesc::readU8(b,p,x.type)||!Cesc::readU8(b,p,x.status)||!Cesc::readU8(b,p,reserved)||!Cesc::readU16(b,p,x.rawAngle)||!Cesc::readFloat32(b,p,x.degrees)||!Cesc::readU64(b,p,x.timestampUs))return;if(p<b.size()){if(!Cesc::readI32(b,p,x.positionCounts)||!Cesc::readFloat32(b,p,x.positionDegrees)||!Cesc::readU16(b,p,x.electricalRawUnaligned)||!Cesc::readFloat32(b,p,x.electricalDegreesUnaligned)||!Cesc::readU8(b,p,x.polePairs)||!Cesc::readU8(b,p,calibrated)||!Cesc::readU16(b,p,x.electricalZeroRaw)||!Cesc::readU16(b,p,x.electricalRaw)||!Cesc::readFloat32(b,p,x.electricalDegrees))return;x.electricalZeroCalibrated=calibrated!=0;}emit sampleReceived(x);}});}
void CescSensorClient::enumerate(){m_session->transactions()->request(2,0,{});}void CescSensorClient::getSample(quint8 id){m_session->transactions()->request(2,1,QByteArray(1,char(id)));}void CescSensorClient::getStatus(quint8 id){m_session->transactions()->request(2,2,QByteArray(1,char(id)));}
